"deteriorate":{a:[{tr:"f. kötüleşmek, bozulmak, gerilemek",ex:"Without proper maintenance, the bridge's structure began to deteriorate much faster than engineers expected.",exTr:"Uygun bakım yapılmadığında, köprünün yapısı mühendislerin beklediğinden çok daha hızlı bozulmaya başladı."}],es:"worsen, decline"},
"disappointed":{a:[{tr:"s. hayal kırıklığına uğramış",ex:"Investors seemed disappointed after the company reported weaker earnings than analysts had predicted.",exTr:"Şirket, analistlerin öngördüğünden daha zayıf kazanç bildirince yatırımcılar hayal kırıklığına uğramış görünüyordu."}]},
"disguise":{a:[{tr:"i. kılık değiştirme, maske; f. kılık değiştirmek, gizlemek",ex:"The spy wore an elaborate disguise to cross the border without being recognized.",exTr:"Casus, sınırı fark edilmeden geçebilmek için özenle hazırlanmış bir kılık değiştirme kullandı."}]},
"disparity":{a:[{tr:"i. eşitsizlik, uyumsuzluk, fark",ex:"The report highlighted a striking disparity in healthcare access between urban and rural populations.",exTr:"Rapor, kentsel ve kırsal nüfuslar arasındaki sağlık hizmetlerine erişimdeki çarpıcı eşitsizliğe dikkat çekti."}]},
